/* L5X Studio — minimal Mermaid flowchart renderer (offline, no CDN).
 *
 * Supports the subset generated by js/module-usage.js:
 *   flowchart LR | TD
 *   classDef <name> fill:#..,stroke:#..,color:#..
 *   node definitions:  ID["label"]  |  ID["a<br/>b"]  |  ID(label)  |  ID
 *   class suffix:      ID[".."]:::class
 *   edges:             A -->|"label"| B   |   A -->|label| B   |   A --> B   |   A -.-> B
 *
 * Renders to a self-contained SVG string (no DOM required) or into a container when
 * running in a browser. Layout is a layered left-to-right (or top-to-bottom) DAG.
 */
(function (factory) {
  if (typeof module === "object" && module.exports) {
    module.exports = factory();
  } else {
    var root = typeof window !== "undefined" ? window : this;
    root.L5XStudio = root.L5XStudio || {};
    root.L5XStudio = Object.assign(root.L5XStudio, factory());
  }
})(function () {
  "use strict";

  function esc(s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  /* -------- parser -------- */
  function parse(text) {
    const lines = String(text || "").split(/\r?\n/);
    const direction = /flowchart\s+TD|graph\s+TD/i.test(lines[0] || "") ? "TD" : "LR";
    const nodes = {};       // id -> {id, label, cls}
    const edges = [];       // {from, to, label, dashed}
    const styles = {};      // class -> {fill, stroke, color}
    const order = [];
    function ensureNode(id) {
      if (!nodes[id]) {
        nodes[id] = { id: id, label: id, cls: "" };
        order.push(id);
      }
      return nodes[id];
    }
    for (let i = 0; i < lines.length; i++) {
      let line = lines[i].trim();
      if (!line || /^(flowchart|graph|%%|subgraph|end)\b/i.test(line)) continue;
      if (/^classDef\s+/i.test(line)) {
        const m = /^classDef\s+(\S+)\s+(.+)$/i.exec(line);
        if (m) {
          const st = {};
          m[2].split(",").forEach(function (kv) {
            const p = kv.split(":");
            if (p.length >= 2) st[p[0].trim()] = p.slice(1).join(":").trim();
          });
          styles[m[1]] = st;
        }
        continue;
      }
      if (/^class\s+/i.test(line)) {
        const m = /^class\s+(\S+)\s+(\S+)$/i.exec(line);
        if (m) m[1].split(",").forEach(function (id) { if (nodes[id]) nodes[id].cls = m[2]; });
        continue;
      }
      const edgeRe = /^(\S+?)\s*(-->|-.->|---)\s*(\|"?([^"|]*)"?\|)?\s*(\S+)$/;
      const em = edgeRe.exec(line);
      if (em) {
        const from = ensureNode(em[1]);
        const to = ensureNode(em[5]);
        edges.push({ from: from.id, to: to.id, label: (em[4] || "").trim(), dashed: em[2] === "-.->" || em[2] === "---" });
        continue;
      }
      // node definition: ID["label"] or ID(label) with an optional :::class suffix
      let nodeText = line;
      const clsSuffix = /:::(\S+)$/.exec(nodeText);
      let nodeCls = "";
      if (clsSuffix) { nodeCls = clsSuffix[1]; nodeText = nodeText.slice(0, clsSuffix.index).trim(); }
      const nm = /^([A-Za-z0-9_]+)\s*(\["([^"]*)"\]|\(([^)]*)\)|\[([^\]]*)\])?$/.exec(nodeText);
      if (nm) {
        const n = ensureNode(nm[1]);
        if (nm[3] !== undefined) n.label = nm[3];
        else if (nm[4] !== undefined) n.label = nm[4];
        else if (nm[5] !== undefined) n.label = nm[5];
        if (nodeCls) n.cls = nodeCls;
      }
    }
    return { direction: direction, nodes: nodes, order: order, edges: edges, styles: styles };
  }

  /* -------- layout -------- */
  function layout(graph) {
    const ids = graph.order;
    const layer = {};
    ids.forEach(function (id) { layer[id] = 0; });
    // longest path from sources (bounded relaxation, handles cycles)
    const maxIter = ids.length * 2;
    for (let it = 0; it < maxIter; it++) {
      let changed = false;
      for (const e of graph.edges) {
        if (layer[e.from] + 1 > layer[e.to]) { layer[e.to] = layer[e.from] + 1; changed = true; }
      }
      if (!changed) break;
    }
    const layers = {};
    ids.forEach(function (id) { (layers[layer[id]] = layers[layer[id]] || []).push(id); });
    const labelLines = function (n) { return String(n.label).split("<br/>").map(function (s) { return s.replace(/&nbsp;/g, " "); }); };
    const nodeSize = function (n) {
      const lines = labelLines(n);
      const w = Math.max(70, Math.min(360, Math.max.apply(null, lines.map(function (l) { return l.length; })) * 7.2 + 22));
      const h = Math.max(30, lines.length * 15 + 14);
      return { w: w, h: h, lines: lines };
    };
    const gapX = 70, gapY = 26;
    const layerKeys = Object.keys(layers).map(Number).sort(function (a, b) { return a - b; });
    /* A layer with very many nodes is wrapped into side-by-side columns so a large
       module network stays readable (instead of a 10,000 px tall single column). */
    const maxPerColumn = 22;
    const positions = {};
    let x = 30, maxH = 0;
    for (const k of layerKeys) {
      const ids = layers[k];
      let colW = 60;
      for (const id of ids) colW = Math.max(colW, nodeSize(graph.nodes[id]).w);
      let chunkOffset = 0;
      for (let i = 0; i < ids.length; i += maxPerColumn) {
        const chunk = ids.slice(i, i + maxPerColumn);
        let y = 30;
        for (const id of chunk) {
          const n = graph.nodes[id];
          const s = nodeSize(n);
          positions[id] = { x: x + chunkOffset, y: y, w: s.w, h: s.h, lines: s.lines, node: n };
          y += s.h + gapY;
          maxH = Math.max(maxH, y);
        }
        chunkOffset += colW + gapX;
      }
      x += chunkOffset;
    }
    const width = x + 20, height = maxH + 20;
    // convert to TD when requested
    if (graph.direction === "TD") {
      const p2 = {};
      for (const id of ids) {
        const p = positions[id];
        p2[id] = { x: p.y, y: p.x, w: p.h, h: p.w, lines: p.lines, node: p.node };
      }
      return { positions: p2, width: height, height: width };
    }
    return { positions: positions, width: width, height: height };
  }

  /* -------- render -------- */
  const DEFAULT_STYLE = {
    used: { fill: "#1b5e20", stroke: "#66bb6a", color: "#e8f5e9" },
    mapped: { fill: "#1565c0", stroke: "#42a5f5", color: "#e3f2fd" },
    unused: { fill: "#263238", stroke: "#455a64", color: "#90a4ae" },
    module: { fill: "#0d47a1", stroke: "#64b5f6", color: "#ffffff" },
    net: { fill: "#004d40", stroke: "#26a96c", color: "#ffffff" },
    hw: { fill: "#e65100", stroke: "#ffb74d", color: "#ffffff" },
    sub: { fill: "#37474f", stroke: "#78909c", color: "#ffffff" },
    controller: { fill: "#311b92", stroke: "#9575cd", color: "#ffffff" },
    tag: { fill: "#4a148c", stroke: "#ba68c8", color: "#f3e5f5" },
    routine: { fill: "#e65100", stroke: "#ffb74d", color: "#fff3e0" }
  };

  function styleFor(cls, styles) {
    const name = String(cls || "").trim();
    if (styles && styles[name]) {
      const s = styles[name];
      return { fill: s.fill || "#263238", stroke: s.stroke || "#455a64", color: s.color || "#e6edf3" };
    }
    if (DEFAULT_STYLE[name]) return DEFAULT_STYLE[name];
    return { fill: "#16202b", stroke: "#3a4a5c", color: "#d7e1ec" };
  }

  function renderToSvg(text, opts) {
    opts = opts || {};
    const graph = parse(text);
    const laid = layout(graph);
    const pad = 18;
    const W = Math.ceil(laid.width + pad * 2), H = Math.ceil(laid.height + pad * 2);
    const out = [];
    out.push("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"" + W + "\" height=\"" + H +
      "\" viewBox=\"0 0 " + W + " " + H + "\" font-family=\"Segoe UI, Arial, sans-serif\">");
    out.push("<style>.mm-label{font-size:12px;font-weight:600}.mm-edge-label{font-size:10px}</style>");
    out.push("<rect width=\"" + W + "\" height=\"" + H + "\" fill=\"" + (opts.background || "#0e1319") + "\"/>");
    // edges first (under nodes)
    for (const e of graph.edges) {
      const a = laid.positions[e.from], b = laid.positions[e.to];
      if (!a || !b) continue;
      const x1 = a.x + a.w + pad, y1 = a.y + a.h / 2 + pad;
      const x2 = b.x + pad, y2 = b.y + b.h / 2 + pad;
      const mid = Math.max(x1 + 20, (x1 + x2) / 2);
      out.push("<path d=\"M " + x1 + " " + y1 + " C " + mid + " " + y1 + " " + (x2 - 30) + " " + y2 + " " + x2 + " " + y2 +
        "\" fill=\"none\" stroke=\"" + (e.dashed ? "#4a5a6a" : "#3f6c8f") + "\" stroke-width=\"1.4\"" +
        (e.dashed ? " stroke-dasharray=\"5 4\"" : "") + " marker-end=\"url(#mm-arrow)\"/>");
      if (e.label) {
        const lx = (x1 + x2) / 2, ly = (y1 + y2) / 2 - 4;
        out.push("<text class=\"mm-edge-label\" x=\"" + lx + "\" y=\"" + ly + "\" text-anchor=\"middle\" fill=\"#9fb6c9\">" + esc(e.label) + "</text>");
      }
    }
    out.push("<defs><marker id=\"mm-arrow\" markerWidth=\"9\" markerHeight=\"9\" refX=\"8\" refY=\"4.5\" orient=\"auto\">" +
      "<path d=\"M0,0 L9,4.5 L0,9 z\" fill=\"#7fa8c9\"/></marker></defs>");
    for (const id of graph.order) {
      const p = laid.positions[id];
      if (!p) continue;
      const st = styleFor(p.node.cls, opts.styles || graph.styles);
      const x = p.x + pad, y = p.y + pad;
      out.push("<rect x=\"" + x + "\" y=\"" + y + "\" width=\"" + Math.max(40, p.w) + "\" height=\"" + Math.max(24, p.h) +
        "\" rx=\"6\" fill=\"" + st.fill + "\" stroke=\"" + st.stroke + "\" stroke-width=\"1.4\"/>");
      const lineH = 15;
      const startY = y + p.h / 2 - ((p.lines.length - 1) * lineH) / 2 + 4;
      for (let i = 0; i < p.lines.length; i++) {
        out.push("<text class=\"mm-label\" x=\"" + (x + 10) + "\" y=\"" + (startY + i * lineH) + "\" fill=\"" + st.color + "\">" + esc(p.lines[i]) + "</text>");
      }
    }
    out.push("</svg>");
    return out.join("\n");
  }

  function renderInto(container, text, opts) {
    if (!container) return null;
    container.innerHTML = renderToSvg(text, opts);
    return container;
  }

  return { parse: parse, layout: layout, renderToSvg: renderToSvg, renderInto: renderInto, DEFAULT_STYLE: DEFAULT_STYLE };
});
